import zipfile
import xml.etree.ElementTree as ET

# Classification keywords
keywords_by_category = {
    'LLM': ['language model', 'llm', 'transformer', 'bert', 'gpt', 'neural network',
            'deep learning', 'attention', 'embedding', 'nlm', 'nlp', 'natural language'],
    'trapped_ion_and_qc': ['trapped ion', 'ion trap', 'quantum computing', 'quantum computer',
                            'qubit', 'quantum gate', 'quantum algorithm', 'quantum'],
    'black_hole': ['black hole', 'event horizon', 'singularity', 'hawking', 'gravitational'],
    'DNA': ['dna', 'genetics', 'gene', 'protein', 'mutation', 'chromosome', 'genome'],
    'music_history': ['music', 'musical', 'composer', 'symphony', 'harmony', 'melody']
}

def classify_text(text):
    text_lower = text.lower()
    scores = {}
    for category, keywords in keywords_by_category.items():
        scores[category] = sum(1 for kw in keywords if kw in text_lower)
    best = max(scores, key=scores.get)
    return best if scores[best] > 0 else 'music_history'

# Process DOCX files
for filename in ['paper_file_1.docx', 'paper_file_2.docx']:
    try:
        with zipfile.ZipFile(f'/root/papers/all/{filename}') as z:
            text = ''
            for name in z.namelist():
                if 'document.xml' in name:
                    xml_content = z.read(name).decode('utf-8')
                    # Extract text from XML
                    root = ET.fromstring(xml_content)
                    for elem in root.iter():
                        if elem.text:
                            text += elem.text + ' '
            subject = classify_text(text)
            print(f"{filename},{subject}")
    except Exception as e:
        print(f"Error processing {filename}: {e}", flush=True)
        print(f"{filename},music_history")

# Process PPTX file
filename = 'DAMOP.pptx'
try:
    with zipfile.ZipFile(f'/root/papers/all/{filename}') as z:
        text = ''
        for name in z.namelist():
            if 'slide' in name and name.endswith('.xml'):
                try:
                    xml_content = z.read(name).decode('utf-8')
                    root = ET.fromstring(xml_content)
                    for elem in root.iter():
                        if elem.text:
                            text += elem.text + ' '
                except:
                    pass
        subject = classify_text(text)
        print(f"{filename},{subject}")
except Exception as e:
    print(f"Error processing {filename}: {e}", flush=True)
    print(f"{filename},music_history")

